  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Attempts to move an entity from one position to another and updates the game state accordingly.
   * This operation supports player movement and box pushing, and records transitions for undo.
   * Algorithm:
   * 1. Validate that from and to are within board bounds.
   * 2. Fetch the entity at from.
   * 3. If from does not contain a Player, fail.
   * 4. Inspect the entity at to:
   *    a. If to is Empty, move the player into to.
   *    b. If to contains a Box:
   *       i. Verify the box belongs to the moving player.
   *       ii. Compute the position behind the box in the movement direction.
   *       iii. Verify the behind position is empty.
   *       iv. Move the box first, then move the player.
   *       v. Record both atomic moves in currentTransition.
   *       vi. If a box is successfully pushed, checkpoint the transition history.
   *    c. If to contains a Wall, Player, or unpushable Box, fail.
   * 5. Update entities at affected positions.
   * Related Features:
   * - entities: board content to mutate.
   * - currentTransition: accumulates atomic movement steps.
   * - history: stores checkpoints for undo.
   * - destinations: may be relevant for win evaluation after movement.
   * Related Classes: Position, Entity, Player, Box, Empty, Wall, GameStateTransition
   * Input:
   * - from: starting position of the moving player.
   * - to: target adjacent position.
   * Output:
   * - void.
   * Pre-condition:
   * - from and to are valid board positions.
   * - from contains a Player entity.
   * - to is adjacent to from.
   * - If to contains a Box, the box must belong to the moving player and the cell behind it must be Empty.
   * Post-condition:
   * - If the move succeeds, the player is relocated and, when applicable, the box is pushed atomically.
   * - Transition information is recorded so that undo can restore the previous state.
   * - If the move fails, the board remains unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void move(final Position from, final Position to)
  {
    if (from == null || to == null) return;
    if (from.getX() < 0 || from.getX() >= getBoardWidth() || from.getY() < 0 || from.getY() >= getBoardHeight()) return;
    if (to.getX() < 0 || to.getX() >= getBoardWidth() || to.getY() < 0 || to.getY() >= getBoardHeight()) return;

    Entity fromEntity = getEntity(from);
    if (!(fromEntity instanceof Player)) return;

    Entity toEntity = getEntity(to);

    int dx = to.getX() - from.getX();
    int dy = to.getY() - from.getY();

    if (toEntity instanceof Empty) {
      getEntities().put(to, fromEntity);
      getEntities().put(from, Pa22Factory.eINSTANCE.createEmpty());
      GameStateTransition transition = Pa22Factory.eINSTANCE.createGameStateTransition();
      transition.add(from, to);
      currentTransition.getMoves().putAll(transition.getMoves());
      return;
    }

    if (toEntity instanceof Box) {
      Box box = (Box)toEntity;
      Player player = (Player)fromEntity;
      if (box.getPlayerId() != player.getId()) return;

      Position behind = Pa22Factory.eINSTANCE.createPosition();
      behind.setX(to.getX() + dx);
      behind.setY(to.getY() + dy);

      if (behind.getX() < 0 || behind.getX() >= getBoardWidth() || behind.getY() < 0 || behind.getY() >= getBoardHeight()) return;
      Entity behindEntity = getEntity(behind);
      if (!(behindEntity instanceof Empty)) return;

      getEntities().put(behind, toEntity);
      getEntities().put(to, fromEntity);
      getEntities().put(from, Pa22Factory.eINSTANCE.createEmpty());

      if (currentTransition == null) {
        currentTransition = Pa22Factory.eINSTANCE.createGameStateTransition();
      }
      currentTransition.add(to, behind);
      currentTransition.add(from, to);
      checkpoint();
      return;
    }
  }

